/** 按稀有度从池中抽一条结局；先按档位权重 roll 稀有度，再在该稀有度内随机 */
function pickEndingByRarity(pool, tier) {
  const weights = RARITY_WEIGHTS_BY_TIER[tier] || RARITY_WEIGHTS_BY_TIER.normal;
  let r = Math.random();
  let chosenRarity = 'common';
  for (const rarity of RARITIES) {
    r -= weights[rarity] || 0;
    if (r <= 0) { chosenRarity = rarity; break; }
  }
  const filtered = pool.filter(id => (ENDING_RARITY[id] || 'common') === chosenRarity);
  const finalPool = filtered.length > 0 ? filtered : pool;
  return finalPool[Math.floor(Math.random() * finalPool.length)];
}

/** 从池中抽一条结局；根据市场哲学调整 weird 结局概率 */
function pickFromPool(pool, tier, state) {
  const actualTier = tier || 'normal';
  // 使用根据市场哲学调整后的 weird 结局概率
  const weirdChance = state ? getWeirdEndingChance(state) : OTHER_ENDING_CHANCE;
  
  // 检查是否有结局池调整（如虚无主义强制切到 weird 池）
  let finalPool = pool;
  let finalTier = actualTier;
  
  if (state) {
    const adjustment = getAdjustedEndingPool(state, pool, tier);
    if (adjustment.forced) {
      return pickEndingByRarity(adjustment.pool, adjustment.tier);
    }
    finalPool = adjustment.pool;
    finalTier = adjustment.tier;
  }
  
  // 按调整后的概率决定是否进入 weird 结局池
  if (Math.random() < weirdChance && OTHER_ENDINGS.length > 0) {
    return pickEndingByRarity(OTHER_ENDINGS, 'weird');
  }
  return pickEndingByRarity(finalPool, finalTier);
}

/** 净资产 = 现金 - 负债，用于结局与显示 */
function getNetWealth(state) {
  return (state.wealth || 0) - (state.debt || 0);
}

/** 根据初始设定计算「坏结局倾向」0~1：运气差、理性低、风险偏好高 → 更容易坏/悲剧结局 */

/** 
 * 玩家事件配置（用于群聊@消息）
 * 注意：实际数据从 chat-player-events.js 加载 (PLAYER_AT_EVENTS)
 * 这里保留空对象作为fallback
 */
const PLAYER_EVENTS = {}; // 数据由外部文件提供

/** 
 * 触发玩家@事件（决策结果/爆仓/大盈利等）
 * 新逻辑：
 * - 决策失败：强制触发 1-3 条羞辱
 * - 决策成功：50% 概率触发 1 条赞美
 * - 其他事件：使用 PLAYER_AT_EVENTS 配置
 */
function triggerPlayerEvent(eventType, forceTrigger = false, isSuccess = false) {
  // 使用新的数据源
  const events = (typeof PLAYER_AT_EVENTS !== 'undefined') ? PLAYER_AT_EVENTS : PLAYER_EVENTS;
  const event = events[eventType];
  if (!event) return;
  
  // 决策类事件特殊处理
  if (eventType === 'decisionFail') {
    if (isSuccess) {
      // 决策成功：50% 触发 1 条赞美
      if (Math.random() >= 0.5) return;
      const praises = event.praises || [];
      if (praises.length === 0) return;
      const text = praises[Math.floor(Math.random() * praises.length)];
      const user = generateRandomUserForAt();
      addSpecialChatMessage({
        atPlayer: true,
        user: user,
        text: text,
        playerId: game.state.playerId || '玩家'
      });
    } else {
      // 决策失败：强制触发 1-3 条羞辱
      const insults = event.insults || [];
      if (insults.length === 0) return;
      
      const count = 1 + Math.floor(Math.random() * 3); // 1-3条
      for (let i = 0; i < count; i++) {
        const text = insults[Math.floor(Math.random() * insults.length)];
        const user = generateRandomUserForAt();
        setTimeout(() => {
          addSpecialChatMessage({
            atPlayer: true,
            user: user,
            text: text,
            playerId: game.state.playerId || '玩家'
          });
        }, i * 800); // 每条间隔800ms，连续输出
      }
    }
    return;
  }
  
  // 其他事件（爆仓/大赚/大亏）使用原有逻辑但新数据源
  const texts = event.insults || event.praises || [];
  if (texts.length === 0) return;
  
  // 检查概率（强制触发时跳过）
  if (!forceTrigger && event.chance && Math.random() > event.chance) return;
  
  // 检查是否近期已触发过
  const now = Date.now();
  const recentEvents = game.playerEventHistory.filter(e => e.type === eventType && now - e.time < 5000);
  if (recentEvents.length > 0) return; // 5秒内不重复触发
  
  // 记录事件
  game.playerEventHistory.push({ type: eventType, time: now });
  if (game.playerEventHistory.length > 50) {
    game.playerEventHistory = game.playerEventHistory.slice(-20);
  }
  
  // 生成消息
  const text = texts[Math.floor(Math.random() * texts.length)];
  const user = generateRandomUserForAt();
  addSpecialChatMessage({
    atPlayer: true,
    user: user,
    text: text,
    playerId: game.state.playerId || '玩家'
  });
}

