const ACHIEVEMENT_KEY = 'memeMaxAchievements';
const COUNTS_KEY = 'memeMaxCounts';

/** 稀有度排序权重：用于成就列表先已解锁后未解锁、再按稀有度从低到高 */
const ACHIEVEMENT_RARITY_ORDER = { common: 0, uncommon: 1, rare: 2, epic: 3, legendary: 4, mythic: 5, supreme: 6 };

function getCounts() {
  try {
    const raw = localStorage.getItem(COUNTS_KEY);
    return raw ? JSON.parse(raw) : { gamesFinished: 0, wealth1e7: 0, wealth1e8: 0, wealth1e9: 0 };
  } catch (err) { return { gamesFinished: 0, wealth1e7: 0, wealth1e8: 0, wealth1e9: 0 }; }
}

function updateCounts(netWealth) {
  const c = getCounts();
  c.gamesFinished = (c.gamesFinished || 0) + 1;
  if (Number(netWealth) >= 1e9) c.wealth1e9 = (c.wealth1e9 || 0) + 1;
  if (Number(netWealth) >= 1e8) c.wealth1e8 = (c.wealth1e8 || 0) + 1;
  if (Number(netWealth) >= 1e7) c.wealth1e7 = (c.wealth1e7 || 0) + 1;
  // 硬核模式计数
  if (game.decisionMode === 'hardcore') {
    c.hardcoreGamesFinished = (c.hardcoreGamesFinished || 0) + 1;
  }
  try { localStorage.setItem(COUNTS_KEY, JSON.stringify(c)); } catch (err) { return; }
  return c;
}

function getUnlockedAchievements() {
  try {
    const raw = localStorage.getItem(ACHIEVEMENT_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (err) { return []; }
}

function unlockAchievement(id) {
  const list = getUnlockedAchievements();
  if (list.includes(id)) return false;
  list.push(id);
  try { localStorage.setItem(ACHIEVEMENT_KEY, JSON.stringify(list)); } catch (err) { return false; }
  return true;
}

function buildAchievementPayload(s) {
  // 数值统一转为 Number，避免 undefined/字符串导致成就判定失败（如路人甲、归零等）
  const payload = {
    netWealth: Number(getNetWealth(s)),
    fans: Number(s.fans) || 0,
    path: s.mainPath,
    endingId: s.ending,
    year: Number(s.year) || 0,
    week: Number(s.week) || 0,
    hadWindfall100: s.hadWindfall100 === true,
    hadWindfall1000: s.hadWindfall1000 === true,
    hadCatastrophe: s.hadCatastrophe === true,
    pathSaint: s.pathSaint || null,
    debt: Number(s.debt) || 0,
  };
  
  // 硬核模式相关数据
  payload.isHardcore = game.decisionMode === 'hardcore';
  if (payload.isHardcore && typeof hardcoreMode !== 'undefined' && hardcoreMode) {
    const stats = hardcoreMode.getStats ? hardcoreMode.getStats() : {};
    payload.hardcoreCorrectCount = stats.correctDecisions || 0;
    payload.hardcoreTotalDecisions = stats.totalDecisions || 0;
  } else {
    payload.hardcoreCorrectCount = 0;
    payload.hardcoreTotalDecisions = 0;
  }
  // 检查是否有过负资产（用于硬核幸存者成就）
  payload.hadNegativeWealth = (s.wealth < 0) || (payload.netWealth < 0 && s.hadNegativeWealth === true);
  
  return payload;
}

/** 检查并解锁成就，返回本局新解锁的成就 id 列表 */
function checkAndUnlockAchievements(payload) {
  const before = getUnlockedAchievements().slice();
  ACHIEVEMENTS.forEach(a => {
    if (before.includes(a.id)) return;
    if (a.check(payload)) unlockAchievement(a.id);
  });
  const after = getUnlockedAchievements();
  return after.filter(id => !before.includes(id));
}

function renderAchievements() {
  const listEl = document.getElementById('achievementList');
  if (!listEl) return;
  const unlocked = getUnlockedAchievements();
  const sorted = [...ACHIEVEMENTS].sort((a, b) => {
    const uA = unlocked.includes(a.id) ? 1 : 0;
    const uB = unlocked.includes(b.id) ? 1 : 0;
    if (uB !== uA) return uB - uA; // 已解锁在前
    return (ACHIEVEMENT_RARITY_ORDER[a.rarity] ?? 0) - (ACHIEVEMENT_RARITY_ORDER[b.rarity] ?? 0); // 同组内按稀有度从低到高（common 在前）
  });
  listEl.innerHTML = sorted.map(a => {
    const unlocked_ = unlocked.includes(a.id);
    const nameStr = escapeHtml(unlocked_ ? a.name : '？？？');
    const descStr = escapeHtml(unlocked_ ? (a.desc || '') : '未解锁');
    const rawTitle = unlocked_ ? (a.desc || '') : '解锁方式：' + (a.desc || '');
    const titleStr = escapeHtml(rawTitle).replace(/"/g, '&quot;');
    return `<div class="achievement-box rarity-${a.rarity} ${unlocked_ ? 'unlocked' : 'locked'}" title="${titleStr}">
      <div class="achievement-name">${nameStr}</div>
      <div class="achievement-desc">${descStr}</div>
    </div>`;
  }).join('');
  
  // 更新预览卡片上的成就数量
  const previewCount = document.getElementById('previewAchCount');
  if (previewCount) {
    previewCount.textContent = `${unlocked.length}/${ACHIEVEMENTS.length} 已解锁`;
  }
}

const HISTORY_KEY = 'memeMaxHistory';
const HISTORY_MAX = 30;

function saveGameHistory(record) {
  try {
    const list = getGameHistory();
    record.id = Date.now();
    list.unshift(record);
    if (list.length > HISTORY_MAX) list.length = HISTORY_MAX;
    localStorage.setItem(HISTORY_KEY, JSON.stringify(list));
  } catch (err) { /* quota or disabled */ }
  
  // 上报到在线排行榜（如果启用了）
  if (typeof submitGameResult === 'function' && game.state) {
    submitGameResult(game.state);
  }
}

function getGameHistory() {
  try {
    const raw = localStorage.getItem(HISTORY_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (err) { return []; }
}

function updateUI() {
  const s = game.state;
  if (!s) return;
  const netW = getNetWealth(s);
  const wealthEl = document.getElementById('dispWealth');
  wealthEl.textContent = formatU(netW);
  if (netW < 0) wealthEl.classList.add('negative'); else wealthEl.classList.remove('negative');
  document.getElementById('dispPath').textContent = (PATHS.find(p => p.id === s.mainPath) || {}).name || s.mainPath;
  const playerIdEl = document.getElementById('dispPlayerId');
  if (playerIdEl) {
    const pid = (s.playerId || '').trim();
    playerIdEl.textContent = pid ? 'ID: ' + pid : '—';
    playerIdEl.setAttribute('data-empty', pid ? 'false' : 'true');
  }
  const timeEl = document.getElementById('dispTime');
  if (timeEl) timeEl.textContent = `第 ${s.year + 1}/${MAX_YEARS} 年 ${s.week + 1} 月`;
  const phaseEl = document.getElementById('phaseName');
  const phaseIcon = document.getElementById('phaseIcon');
  const phaseMoodFear = document.getElementById('phaseMoodFear');
  
  // 市场阶段图标
  if (phaseIcon) {
    phaseIcon.textContent = game.marketPhase === 'bull' ? '🐂' : game.marketPhase === 'bear' ? '🐻' : '➡️';
  }
  
  // 市场阶段 + 年份
  if (phaseEl) {
    const phaseName = game.marketPhase === 'bull' ? '牛市' : game.marketPhase === 'bear' ? '熊市' : '横盘';
    phaseEl.textContent = `${phaseName}·第${s.year + 1}年`;
  }
  
  // 情绪 + 恐惧指数（简化左侧显示）
  if (phaseMoodFear) {
    // 计算恐惧/贪婪指数
    const baseIndex = game.marketPhase === 'bull' ? 75 : game.marketPhase === 'bear' ? 25 : 50;
    const volatilityImpact = Math.min(15, (game.simVolatility || 20) / 3);
    const fearGreed = Math.max(0, Math.min(100, baseIndex + (Math.random() - 0.5) * volatilityImpact * 2));
    
    let moodIcon, moodText;
    if (fearGreed >= 75) { moodIcon = '😎'; moodText = '贪婪'; }
    else if (fearGreed >= 50) { moodIcon = '🙂'; moodText = '乐观'; }
    else if (fearGreed >= 25) { moodIcon = '😰'; moodText = '恐惧'; }
    else { moodIcon = '😱'; moodText = '极度恐惧'; }
    
    phaseMoodFear.textContent = `${moodIcon} ${moodText} ${Math.round(fearGreed)}`;
  }
  renderChart();
  renderMiniChart();
  renderLog();
}

function formatU(n) {
  // 使用紧凑货币格式显示，保留K,M，>=1B用e+科学计数法(基于B)
  const num = Number(n) || 0;
  const absNum = Math.abs(num);
  const sign = num < 0 ? '-' : '';
  
  // 小于1000直接显示（等于0显示$0，小于1显示<$1，1-999显示整数）
  if (absNum < 1e3) {
    if (absNum === 0) return '$0';
    if (absNum < 1) return sign + '<$1';
    return sign + '$' + Math.round(absNum);
  }
  
  // 1K-999M用K,M表示
  if (absNum >= 1e3 && absNum < 1e9) {
    if (absNum >= 1e6) {
      return sign + '$' + (absNum / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    }
    return sign + '$' + (absNum / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
  }
  
  // 大于等于1B(1e9)：转换为以B为单位的科学计数法
  // 例如 1.5e15 → 1.5e15 / 1e9 = 1.5e6 → 显示为 1.5e+6B
  const billions = absNum / 1e9;
  const exponent = Math.floor(Math.log10(billions));
  const mantissa = billions / Math.pow(10, exponent);
  const mantissaStr = mantissa.toString().slice(0, 5);
  return sign + '$' + mantissaStr + 'e+' + exponent + 'B';
}

function formatNumber(n) {
  // 纯数字格式化，不带$符号（用于粉丝数等）
  const num = Number(n) || 0;
  const isNegative = num < 0;
  const absNum = Math.abs(num);
  
  let result;
  if (absNum >= 1e12) {
    result = (absNum / 1e12).toFixed(1) + 'T';
  } else if (absNum >= 1e9) {
    result = (absNum / 1e9).toFixed(2) + 'B';
  } else if (absNum >= 1e6) {
    result = (absNum / 1e6).toFixed(2) + 'M';
  } else if (absNum >= 1e3) {
    result = (absNum / 1e3).toFixed(1) + 'K';
  } else {
    result = absNum.toFixed(0);
  }
  
  // 负数时添加负号
  return isNegative ? '-' + result : result;
}

function renderChart() {
  const line = document.getElementById('chartLine');
  if (!line || !game.marketHistory.length) return;
  const h = game.marketHistory;
  const len = h.length;
  const min = Math.min(...h);
  const max = Math.max(...h) || 1;
  const range = max - min || 1;
  const pts = h.map((v, i) => `${(i / (len - 1 || 1)) * 100}% ${100 - ((v - min) / range) * 80}%`).join(', ');
  line.style.clipPath = `polygon(0 100%, ${pts}, 100% 100%)`;
}

/** 绘制右侧迷你行情图 */
function renderMiniChart() {
  const canvas = document.getElementById('miniMarketChart');
  if (!canvas || !game.marketHistory.length) return;
  
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;
  const h = game.marketHistory;
  
  // 清空画布
  ctx.clearRect(0, 0, width, height);
  
  if (h.length < 2) return;
  
  // 计算范围
  const min = Math.min(...h);
  const max = Math.max(...h);
  const range = max - min || 0.001;
  
  // 确定颜色
  const trend = h[h.length - 1] - h[h.length - 2];
  const color = trend >= 0 ? '#0ecb81' : '#f6465d';
  
  // 绘制折线
  ctx.beginPath();
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  
  for (let i = 0; i < h.length; i++) {
    const x = (i / (h.length - 1)) * width;
    const y = height - ((h[i] - min) / range) * (height - 6) - 3;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();
  
  // 绘制渐变填充
  ctx.beginPath();
  for (let i = 0; i < h.length; i++) {
    const x = (i / (h.length - 1)) * width;
    const y = height - ((h[i] - min) / range) * (height - 6) - 3;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.lineTo(width, height);
  ctx.lineTo(0, height);
  ctx.closePath();
  
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, trend >= 0 ? 'rgba(14,203,129,0.3)' : 'rgba(246,70,93,0.3)');
  gradient.addColorStop(1, trend >= 0 ? 'rgba(14,203,129,0.05)' : 'rgba(246,70,93,0.05)');
  ctx.fillStyle = gradient;
  ctx.fill();
  
  // 绘制最新点
  const lastX = width;
  const lastY = height - ((h[h.length - 1] - min) / range) * (height - 6) - 3;
  ctx.beginPath();
  ctx.fillStyle = color;
  ctx.arc(lastX - 2, lastY, 2, 0, Math.PI * 2);
  ctx.fill();
}

function renderPathList() {
  const el = document.getElementById('pathList');
  if (!el) return;
  const s = game.state;
  if (!s) return;
  const p = PATHS.find(x => x.id === s.mainPath) || PATHS[0];
  el.innerHTML = `<div class="path-item current"><span>${p.icon} ${p.name}</span></div>`;
}

function bindSpeedSelect() {
  const el = document.getElementById('speedSelect');
  if (!el) return;
  el.addEventListener('change', () => {
    const speed = Math.max(1, Math.min(100, parseInt(el.value, 10) || 1));
    game.speed = speed;
    if (!game.paused) startTickLoop();
  });
}

function bindPause() {
  const btn = document.getElementById('btnPause');
  if (!btn) return;
  
  // 移除旧的事件监听器（通过克隆节点）
  const newBtn = btn.cloneNode(true);
  btn.parentNode.replaceChild(newBtn, btn);
  
  newBtn.addEventListener('click', () => {
    const g = game;
    if (!g) return;
    
    if (g.paused) {
      g.paused = false;
      startTickLoop();
      newBtn.textContent = '⏸ 暂停';
    } else {
      g.paused = true;
      if (g.tickInterval) { clearInterval(g.tickInterval); g.tickInterval = null; }
      newBtn.textContent = '▶ 继续';
    }
  });
}

function openLastRunModal() {
  const r = game.lastRunSummary;
  if (!r) return;
  document.getElementById('lastRunTitle').textContent = r.title || '上一局';
  const metaParts = [formatU(r.wealth), '第 ' + (r.year + 1) + ' 年 ' + (r.week + 1) + ' 月', (PATHS.find(p => p.id === r.path) || {}).name || r.path];
  if (r.playerId) metaParts.unshift('ID: ' + r.playerId);
  document.getElementById('lastRunMeta').textContent = metaParts.join(' · ');
  document.getElementById('lastRunStory').textContent = r.story || '';
  const achEl = document.getElementById('lastRunAch');
  achEl.innerHTML = (r.unlockedThisRun && r.unlockedThisRun.length) ? '本局解锁成就：' + r.unlockedThisRun.map(a => a.name).join('、') : '';
  const logEl = document.getElementById('lastRunLog');
  logEl.innerHTML = (r.eventLog && r.eventLog.length) ? r.eventLog.map(e => '<div class="log-line ' + (e.type || '') + '">' + escapeHtml(e.time || '') + ' ' + escapeHtml(e.text || '') + '</div>').join('') : '<p>无日志</p>';
  document.getElementById('lastRunOverlay').classList.add('show');
}

function bindLastRun() {
  document.getElementById('btnLastRun')?.addEventListener('click', openLastRunModal);
  document.getElementById('lastRunClose')?.addEventListener('click', () => document.getElementById('lastRunOverlay')?.classList.remove('show'));
  document.getElementById('lastRunOverlay')?.addEventListener('click', (ev) => { if (ev.target.id === 'lastRunOverlay') ev.target.classList.remove('show'); });
}

/** 仅收起结局弹层，留在本局界面，显示「查看上一局」「再来一局」栏 */
function dismissEndingOnly() {
  // 隐藏结局海报界面
  document.getElementById('endingScreen').classList.remove('show');
  // 显示底部操作栏（包含"显示结局"和"再来一局"按钮）
  const bar = document.getElementById('afterEndBar');
  if (bar) bar.style.display = 'flex';
  const btnPause = document.getElementById('btnPause');
  if (btnPause) btnPause.style.display = 'none';
  
  // 触发结局聊天（10条消息，每秒1条）
  startEndingChat();
}

/** 触发结局聊天 - 10条消息，每秒1条 */
function startEndingChat() {
  const container = document.getElementById('chatMessages');
  if (!container) return;
  
  // 清空现有消息
  container.innerHTML = '';
  
  // 根据财富确定结局类型
  const wealth = getNetWealth(game.state);
  let category = 'normal';
  if (wealth > 1000000) category = 'rich';
  else if (wealth < 0) category = 'bankrupt';
  
  // 发送10条结局消息
  for (let i = 0; i < 10; i++) {
    setTimeout(() => {
      addEndingChatMessage(i);
    }, i * 1000); // 每秒1条
  }
}

/** 进入开局设置页（隐藏结局栏、显示开始页） */
function goToStartScreen() {
  document.getElementById('endingScreen').classList.remove('show');
  document.getElementById('startScreen').classList.remove('hidden');
  document.body.classList.add('start-open');
  const bar = document.getElementById('afterEndBar');
  if (bar) bar.style.display = 'none';
  const btnLastRun = document.getElementById('btnLastRun');
  if (btnLastRun) btnLastRun.style.display = game.lastRunSummary ? '' : 'none';
}

function bindRestart() {
  // 显示结局按钮 - 重新显示海报
  document.getElementById('btnShowEnding')?.addEventListener('click', () => {
    const bar = document.getElementById('afterEndBar');
    if (bar) bar.style.display = 'none';
    document.getElementById('endingScreen').classList.add('show');
  });
  
  // 再来一局按钮已移除，从游戏界面底部栏(afterEndBar)的按钮重新开始
  // 收起结局海报
  document.getElementById('btnEndingDismiss')?.addEventListener('click', () => {
    dismissEndingOnly();
  });
  
  // 保存海报按钮
  document.getElementById('btnDownloadPoster')?.addEventListener('click', () => {
    const canvas = document.getElementById('endingPosterCanvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `mememax-ending-${Date.now()}.png`;
      link.href = canvas.toDataURL();
      link.click();
    }
  });
  
  // 分享按钮
  document.getElementById('btnShareTwitter')?.addEventListener('click', () => {
    const s = game.state;
    if (!s) return;
    const ending = LIFE_ENDINGS[s.ending] || LIFE_ENDINGS.bankruptcy;
    const rarity = ENDING_RARITY[s.ending] || 'common';
    const emoji = {common:'⚪',uncommon:'🟢',rare:'🔵',epic:'🟣',legendary:'🟠',mythic:'🔴',supreme:'🟡'};
    const netW = getNetWealth(s);
    
    const text = `🎉 刚刚在《币圈生涯模拟器》达成了【${ending.title}】！\n\n💰 净资产：${formatU(netW)}\n⏱️ 存活：${s.year + 1}年\n${emoji[rarity]} 稀有度：${rarity.toUpperCase()}\n\n${ending.desc}\n\n👉 mememax-edition.vercel.app`;
    
    const twitterUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`;
    window.open(twitterUrl, '_blank');
  });
  
  document.getElementById('btnRestartFromBar')?.addEventListener('click', () => {
    const bar = document.getElementById('afterEndBar');
    if (bar) bar.style.display = 'none';
    // 使用保存的设置开始新游戏
    const styleMap = {
      degen: { riskPreference: 0.85, rationality: 0.3, strategy: 0.2, social: 0.6, luck: 0.5 },
      balanced: { riskPreference: 0.5, rationality: 0.5, strategy: 0.5, social: 0.5, luck: 0.5 },
      diamond: { riskPreference: 0.3, rationality: 0.7, strategy: 0.9, social: 0.4, luck: 0.5 }
    };
    const baseTraits = styleMap[savedSettings.style] || styleMap.balanced;
    const philosophyMap = {
      technical: { luckMod: 0, rationalityMod: 0.15 },
      news: { luckMod: 0.05, rationalityMod: -0.05 },
      value: { luckMod: -0.05, rationalityMod: 0.1 },
      nihilism: { luckMod: -0.1, rationalityMod: 0 }
    };
    const philEffects = philosophyMap[savedSettings.philosophy] || philosophyMap.news;
    const personalityMap = {
      pragmatist: { weirdMod: -0.08 },
      balanced: { weirdMod: 0 },
      dreamer: { weirdMod: 0.12 }
    };
    const personalityEffects = personalityMap[savedSettings.personality] || personalityMap.balanced;
    
    // 获取保存的玩家ID
    let savedPlayerId = '';
    try { savedPlayerId = localStorage.getItem('memeMaxPlayerId') || ''; } catch (e) {}
    
    const traits = {
      luck: Math.max(0, Math.min(1, baseTraits.luck + philEffects.luckMod)),
      social: baseTraits.social,
      rationality: Math.max(0, Math.min(1, baseTraits.rationality + philEffects.rationalityMod)),
      strategy: baseTraits.strategy,
      riskPreference: baseTraits.riskPreference,
      style: savedSettings.style,
      philosophy: savedSettings.philosophy,
      personality: savedSettings.personality,
      weirdMod: personalityEffects.weirdMod,
      playerId: savedPlayerId
    };
    game.state = null;
    game.running = false;
    // 同步决策模式
    game.decisionMode = savedSettings.decisionMode || 'auto';
    startNewGame(1000, traits);
  });
  // 结局收起后显示"查看历史"按钮
  document.getElementById('btnHistoryFromBar')?.addEventListener('click', openHistoryModal);
}

function openHistoryModal() {
  const overlay = document.getElementById('historyOverlay');
  const listEl = document.getElementById('historyList');
  const detailEl = document.getElementById('historyDetail');
  if (!overlay || !listEl) return;
  detailEl.style.display = 'none';
  listEl.style.display = '';
  const list = getGameHistory();
  listEl.innerHTML = list.length === 0
    ? '<p class="history-item" style="cursor:default;">暂无历史对局</p>'
    : list.map(r => {
        const pathName = (PATHS.find(p => p.id === r.path) || {}).name || r.path || '-';
        const metaParts = [formatU(r.wealth != null ? r.wealth : 0), '第' + ((r.year != null ? r.year : 0) + 1) + '年' + ((r.week != null ? r.week : 0) + 1) + '月', pathName];
        if (r.playerId) metaParts.unshift('ID: ' + escapeHtml(r.playerId));
        return `<div class="history-item" data-id="${r.id}">
          <span class="hi-title">${escapeHtml(r.title || '未命名')}</span>
          <div class="hi-meta">${metaParts.join(' · ')}</div>
        </div>`;
      }).join('');
  listEl.querySelectorAll('.history-item[data-id]').forEach(el => {
    el.addEventListener('click', () => showHistoryDetail(Number(el.dataset.id)));
  });
  overlay.classList.add('show');
}

function showHistoryDetail(id) {
  const list = getGameHistory();
  const r = list.find(x => x.id === id);
  const listEl = document.getElementById('historyList');
  const detailEl = document.getElementById('historyDetail');
  const titleEl = document.getElementById('historyDetailTitle');
  const metaEl = document.getElementById('historyDetailMeta');
  const logEl = document.getElementById('historyDetailLog');
  if (!r || !detailEl) return;
  listEl.style.display = 'none';
  detailEl.style.display = 'block';
  titleEl.textContent = r.title || '未命名';
  const detailMetaParts = [formatU(r.wealth != null ? r.wealth : 0), '粉丝 ' + formatU(r.fans || 0), '第 ' + ((r.year != null ? r.year : 0) + 1) + ' 年 ' + ((r.week != null ? r.week : 0) + 1) + ' 月'];
  if (r.playerId) detailMetaParts.unshift('ID: ' + r.playerId);
  metaEl.textContent = detailMetaParts.join(' · ');
  const storyEl = document.getElementById('historyDetailStory');
  if (storyEl) {
    storyEl.textContent = r.story || '';
    storyEl.style.display = (r.story ? 'block' : 'none');
  }
  const log = (r.eventLog || []);
  logEl.innerHTML = log.length === 0
    ? '<p>无日志</p>'
    : log.map(e => `<div class="log-line ${e.type || ''}">${escapeHtml(e.time || '')} ${escapeHtml(e.text || '')}</div>`).join('');
}

function escapeHtml(s) {
  const div = document.createElement('div');
  div.textContent = s;
  return div.innerHTML;
}

function bindHistoryUI() {
  const overlay = document.getElementById('historyOverlay');
  document.getElementById('btnHistory')?.addEventListener('click', openHistoryModal);
  document.getElementById('historyClose')?.addEventListener('click', () => overlay?.classList.remove('show'));
  document.getElementById('historyDetailBack')?.addEventListener('click', () => {
    document.getElementById('historyDetail').style.display = 'none';
    document.getElementById('historyList').style.display = '';
  });
}

/** 设置面板 UI 绑定 */
function bindSettingsUI() {
  const btnSettings = document.getElementById('btnSettings');
  const overlay = document.getElementById('settingsOverlay');
  const form = document.getElementById('settingsForm');
  const btnCancel = document.getElementById('settingsCancel');
  const styleSelect = document.getElementById('settingStyle');
  const philSelect = document.getElementById('settingPhilosophy');
  const personalitySelect = document.getElementById('settingPersonality');
  const decisionModeSelect = document.getElementById('settingDecisionMode');
  
  if (!btnSettings || !overlay) {
    console.warn('Settings UI elements not found');
    return;
  }
  
  // 打开设置面板
  btnSettings.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    // 同步当前保存的设置为面板值
    if (styleSelect) styleSelect.value = savedSettings.style;
    if (philSelect) philSelect.value = savedSettings.philosophy;
    if (personalitySelect) personalitySelect.value = savedSettings.personality;
    if (decisionModeSelect) decisionModeSelect.value = savedSettings.decisionMode || 'auto';
    overlay.classList.add('show');
    console.log('Settings opened');
  });
  
  // 保存设置
  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const style = styleSelect?.value || 'balanced';
      const philosophy = philSelect?.value || 'news';
      const personality = personalitySelect?.value || 'balanced';
      const decisionMode = decisionModeSelect?.value || 'auto';
      savedSettings = { style, philosophy, personality, decisionMode };
      // 持久化到 localStorage
      saveSettingsToStorage(savedSettings);
      overlay.classList.remove('show');
      showToast('设置已保存，将在下一局生效');
      console.log('Settings saved:', savedSettings);
    });
  }
  
  // 取消
  if (btnCancel) {
    btnCancel.addEventListener('click', (e) => {
      e.preventDefault();
      overlay.classList.remove('show');
    });
  }
  
  // 点击遮罩关闭
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) overlay.classList.remove('show');
  });
  
  // ESC键关闭
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && overlay.classList.contains('show')) {
      overlay.classList.remove('show');
    }
  });
}

/** 显示临时提示 */
function showToast(message) {
  let toast = document.getElementById('gameToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'gameToast';
    toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.85);color:#fff;padding:10px 20px;border-radius:8px;font-size:13px;z-index:3000;opacity:0;transition:opacity 0.3s;pointer-events:none;';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.style.opacity = '1';
  setTimeout(() => { toast.style.opacity = '0'; }, 2000);
}

/** 全局保存的设置（用于新游戏） */
let savedSettings = loadSettingsFromStorage();

/** 从 localStorage 加载设置 */
function loadSettingsFromStorage() {
  const defaults = {
    style: 'balanced',
    philosophy: 'news',
    personality: 'balanced',
    decisionMode: 'hardcore'
  };
  try {
    const stored = localStorage.getItem('memeMaxSettings');
    if (stored) {
      const parsed = JSON.parse(stored);
      // 合并默认值，确保新增字段有默认值
      return { ...defaults, ...parsed };
    }
  } catch (e) {
    console.warn('Failed to load settings from storage:', e);
  }
  return defaults;
}

/** 保存设置到 localStorage */
function saveSettingsToStorage(settings) {
  try {
    localStorage.setItem('memeMaxSettings', JSON.stringify(settings));
  } catch (e) {
    console.warn('Failed to save settings to storage:', e);
  }
}

function initStartForm() {
  const form = document.getElementById('startForm');
  if (!form) return;
  
  // 同步保存的设置到开局表单
  const initStyle = document.getElementById('initStyle');
  const initPhilosophy = document.getElementById('initPhilosophy');
  const initPersonality = document.getElementById('initPersonality');
  const initDecisionMode = document.getElementById('initDecisionMode');
  
  if (initStyle) initStyle.value = savedSettings.style;
  if (initPhilosophy) initPhilosophy.value = savedSettings.philosophy;
  if (initPersonality) initPersonality.value = savedSettings.personality;
  if (initDecisionMode) initDecisionMode.value = savedSettings.decisionMode || 'auto';
  
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    
    const capital = 1000; // 固定本金
    const style = document.getElementById('initStyle')?.value || 'balanced';
    const philosophy = document.getElementById('initPhilosophy')?.value || 'news';
    const personality = document.getElementById('initPersonality')?.value || 'balanced';
    const decisionMode = document.getElementById('initDecisionMode')?.value || 'auto';
    
    // 设置决策模式
    game.decisionMode = decisionMode;
    
    // 保存设置供后续使用
    savedSettings = { style, philosophy, personality, decisionMode };
    // 持久化到 localStorage
    saveSettingsToStorage(savedSettings);
    
    // 根据风格自动计算基础参数
    const styleMap = {
      degen: { riskPreference: 0.85, rationality: 0.3, strategy: 0.2, social: 0.6, luck: 0.5 },
      balanced: { riskPreference: 0.5, rationality: 0.5, strategy: 0.5, social: 0.5, luck: 0.5 },
      diamond: { riskPreference: 0.3, rationality: 0.7, strategy: 0.9, social: 0.4, luck: 0.5 }
    };
    const baseTraits = styleMap[style] || styleMap.balanced;
    
    // 市场哲学影响运气和理性
    const philosophyMap = {
      technical: { luckMod: 0, rationalityMod: 0.15 },
      news: { luckMod: 0.05, rationalityMod: -0.05 },
      value: { luckMod: -0.05, rationalityMod: 0.1 },
      nihilism: { luckMod: -0.1, rationalityMod: 0 }
    };
    const philEffects = philosophyMap[philosophy] || philosophyMap.news;
    
    // 性格特质影响 weird 结局概率
    const personalityMap = {
      pragmatist: { weirdMod: -0.08 },
      balanced: { weirdMod: 0 },
      dreamer: { weirdMod: 0.12 }
    };
    const personalityEffects = personalityMap[personality] || personalityMap.balanced;
    
    const traits = {
      luck: Math.max(0, Math.min(1, baseTraits.luck + philEffects.luckMod)),
      social: baseTraits.social,
      rationality: Math.max(0, Math.min(1, baseTraits.rationality + philEffects.rationalityMod)),
      strategy: baseTraits.strategy,
      riskPreference: baseTraits.riskPreference,
      style: style,             // 操作风格
      philosophy: philosophy,   // 市场哲学
      personality: personality, // 性格特质
      weirdMod: personalityEffects.weirdMod // weird结局概率调整
    };
    
    // 获取玩家ID（从输入框，不再是钱包地址）
    const playerIdInput = document.getElementById('initPlayerId');
    const playerId = (playerIdInput && playerIdInput.value) ? String(playerIdInput.value).trim().slice(0, 32) : '';
    traits.playerId = playerId;
    
    // 保存玩家ID到localStorage供下次使用
    if (playerId) {
      try { localStorage.setItem('memeMaxPlayerId', playerId); } catch (e) {}
    }
    
    document.getElementById('startScreen').classList.add('hidden');
    document.body.classList.remove('start-open');
    startNewGame(capital, traits);
  });
}


